  na = `Dati di iscrizione del debug`,
  ra = `Dati di definizione del debug`,
  ia = `Iscrizione`,
  aa = `Iscriviti fornendo le seguenti informazioni`,
  oa = `Revisione dell'applicazione iscritta: %1$s`,
  sa = `Applicazioni invitate (%1$s)`,
  ca = `Applicazioni con revisione in sospeso (%1$s)`,
  la = `Applicazioni con revisione di appello in sospeso (%1$s)`,
  ua = `Applicazioni rimosse (%1$s)`,
  da = `Svuota lista`,
  fa = `Caricamento appID: %1$s`,
