  ws = `Fornisci una traduzione di tipo "SteamChina - Cinese semplificato" per far apparire queste note all'interno di Steam China`,
  Ts = `Queste note delle patch saranno pubblicate anche su Steam China usando il testo fornito per "SteamChina - Cinese semplificato"`,
