  lE = `Il tuo prezzo attuale è inferiore a quello che normalmente sarebbe consentito impostare per questa valuta. Puoi mantenerlo così com'è, ma ciò rappresenterà un limite a quanto sconto potrai applicare al tuo gioco, poiché il prezzo scontato dovrà comunque rimanere al di sopra dell'importo minimo consentito per una transazione.`,
