  OO = `Uso: le capsule verticali in evidenza appaiono nella pagina principale sotto la sezione "Sconti ed eventi". Questa risorsa è richiesta solo per eventi di saldi dei franchise e degli editori. Le promozioni in evidenza che fanno riferimento a un singolo gioco useranno automaticamente la Capsula verticale del Negozio di quel gioco.`,
