  jO = `Non devono essere inclusi ulteriori testi (es. "Saldi dell'editore", "Weekend gratis", "Fino al 90% di sconto"). Il banner localizzato sovrapposto nella parte superiore di questa risorsa includerà il contesto. L'unica eccezione è il testo "Saldi del franchise".`,
  MO = `Per chiarezza, testi come "Saldi del franchise", "Saldi dell'editore", "Weekend gratis", non dovrebbero essere inclusi`,
