  Uk = `Le immagini devono essere file Photoshop (PSD) a livelli`,
  Wk = `L'immagine principale del gioco/personaggio con la più alta risoluzione disponibile (preferibilmente come smart object). In questo modo possiamo riutilizzare tali risorse per creare, quando necessario, altre immagini promozionali di Steam.`,
