  JA = `Se l'immagine di sfondo o il colore dello sfondo è molto chiaro, la freccia potrebbe essere difficile da vedere. Usa questa impostazione per ignorare il colore bianco predefinito delle frecce delle liste.`,
  YA = `Se il colore dello sfondo o l'immagine dello sfondo sono molto chiari, potrebbe rendere difficile vedere la freccia. Usa questa impostazione per modificare il bianco e il grigio predefiniti del breadcrumb del banner a scorrimento. Appare principalmente su schermi più piccoli, incluso Steam Deck.`,
