  Lj = `Imposta la data di pubblicazione`,
  Rj = `Modifica la tua data di pubblicazione programmata`,
  zj = `Pubblica il più presto possibile: non appena la revisione della build del tuo gioco è completata.`,
  Bj = `Prima data di pubblicazione possibile: %1$s`,
  Vj = `La prima data di pubblicazione possibile è due settimane dopo che la tua pagina del Negozio è rimasta visibile come "In arrivo", oppure 21 giorni dopo il primo acquisto di un credito di pubblicazione (la data più lontana tra queste due). Organizzati di conseguenza.`,
  Hj = `La prima data di pubblicazione possibile è due settimane dopo che la tua pagina del Negozio è rimasta visibile come "In arrivo". Organizzati di conseguenza.`,
  Uj = `Indica la data in cui intendi rilasciare l'applicazione su Steam. Nel caso in cui la data di rilascio fosse ancora lontana, forniscine una plausibile. Se hai bisogno di ritardare il rilascio, dovrai aggiornare la data qui almeno due settimane prima della data precedentemente specificata.`,
  Wj = `Non è possibile rilasciare nel fine settimana, in quanto Valve non è disponibile a fornire assistenza per eventuali problemi di lancio.`,
  Gj = `Tutte le date e gli orari sono nel fuso orario del pacifico (PST).`,
  Kj = `La tua data di pubblicazione prevista è impostata su "%1$s". Se devi modificare questa data, <1>contatta Valve qui</1>, fornendo un motivo per la modifica e una nuova data. Ti invitiamo ad accertarti che la nuova data di lancio sia quella giusta e definitiva.`,
  qj = `NOTA: poiché la tua pagina "In arrivo" può già essere visualizzata dagli utenti, modificare la data del rilascio potrebbe portare alla pubblicazione immediata della tua pagina del Negozio, al fine di rispettare la nuova data impostata. Qualsiasi modifica in sospeso verrà pubblicata ufficialmente.`,
  Jj = `NOTA: la prima data di pubblicazione più vicina che puoi impostare è "%1$s". Potrai utilizzare il pulsante per il rilascio in qualunque momento dopo questa data, indipendentemente da quale essa sia.`,
  Yj = `Modifica`,
