  RL = `Metodi di input generici`,
  zL = `Per descrivere al meglio il livello di supporto per i controller del tuo titolo ai giocatori, abbiamo preparato una procedura guidata con qualche breve domanda. Ti chiediamo di rispondere alle domande al meglio delle tue conoscenze, affinché Steam possa mostrare agli utenti giochi che funzionano bene con i dispositivi in loro possesso.`,
  BL = `Tieni presente che tutti i dispositivi VR, inclusi i dispositivi di input supportati dal gioco, devono essere descritti nei requisiti di sistema. Il supporto per i controller qui descritto deve riferirsi al supporto per desktop o per la modalità Big Picture.`,
