  tR = `Supporto per i controller Xbox`,
  nR = `Se il tuo gioco supporta completamente i controller Xbox, un giocatore potrebbe avviare, configurare, giocare e uscire dal gioco senza accedere a una tastiera. Per confermare che il tuo gioco supporta realmente e completamente i controller Xbox, il gioco deve essere in grado di eseguire le seguenti operazioni:`,
  rR = `Un giocatore dev'essere in grado di eseguire tutte le operazioni nel gioco solo con un controller, tra cui il superamento di qualsiasi launcher pre-gioco, il funzionamento del gioco stesso, l'interazione con i menu, la modifica delle impostazioni e l'uscita dal gioco.`,
  iR = `Quando il controller viene scollegato, il gioco deve andare in pausa, a meno che non si tratti di un gioco multigiocatore.`,
  aR = `Qualsiasi prompt di inserimento del testo deve aprire una tastiera virtuale a schermo.`,
  oR = `Se il tuo gioco supporta la modalità multigiocatore locale, deve funzionare con più controller.`,
  sR = `Il tuo gioco soddisfa i criteri sopra indicati in merito al supporto completo per i controller Xbox?`,
  cR = `Supporto per i controller PlayStation`,
  lR = `Se il gioco supporta uno o più modelli di controller PlayStation elencati di seguito, in genere dovrebbe essere possibile utilizzare tali dispositivi per fare tutto ciò che è possibile fare con i controller Xbox. Inoltre, per essere considerato un gioco in grado di supportare i controller PlayStation, il gioco deve soddisfare le seguenti caratteristiche:`,
  uR = `Visualizzare i glifi (icone) corretti sullo schermo quando viene richiesto all'utente di premere un pulsante specifico sul controller.`,
  dR = `Giocare, interagire con i menu, modificare le impostazioni, uscire.`,
  fR = `<1>Nota USB/Bluetooth:</1> per i controller PlayStation su PC, può essere abbastanza comune che la connessione USB funzioni bene ma non abbia lo stesso livello di supporto se connessa tramite Bluetooth. Conferma con il tuo team tecnico che il gioco funzioni realmente con Bluetooth prima di selezionare quelli riportati di seguito.`,
