  mR = `Integrazione con l'API di Steam Input`,
  hR = `Se il tuo gioco è completamente integrato con l'API di Steam Input, deve funzionare perfettamente con quasi tutti gli oltre 200 modelli di controller che un giocatore può collegare, compresi i modelli futuri. Per dichiarare che il tuo gioco offre realmente tale supporto, dovrebbe essere in grado di eseguire almeno le seguenti operazioni:`,
