  vB = `Questo DLC richiede un altro elemento per funzionare? Seleziona gli elementi necessari del DLC da visualizzare come richiesto. Sul Negozio sarà mostrata automaticamente questa dipendenza, insieme a un'opzione per acquistare tutti gli elementi dipendenti insieme.`,
