  kB = `I pass stagionali sono articoli acquistabili di DLC con la promessa di contenuti futuri che saranno messi a disposizione dei clienti, che si tratti di rilasci di DLC separati o contenuti aggiuntivi sbloccati all'interno del gioco di base.`,
  AB = `Per assumere questo impegno, gli sviluppatori devono descrivere le date di lancio e i relativi contenuti principali inserendo tali informazioni di seguito.`,
  jB = `Usa la sezione generale "Informazioni su questo prodotto (DLC)" qui sopra per descrivere il pass stagionale in generale, utilizzando le date di consegna dei contenuti riportate di seguito per le versioni specifiche dei singoli contenuti.`,
  MB = `Quando hai tutto pronto per comunicare ai giocatori che hai rilasciato contenuti nel pass stagionale, usa l'opzione "Contrassegna come rilasciato" qui sotto e segui le istruzioni. Per ulteriori informazioni, consulta <1>documentazione sul rilascio dei pass stagionali</1>.`,
