  HV = `Collegamento successivo al rilascio dell'obiettivo`,
  UV = `L'obiettivo è già contrassegnato come rilasciato al cliente. Può essere utilizzato per collegare il DLC mancante e l'evento di lancio. Questo aggiornerà semplicemente la visualizzazione una volta pubblicato.`,
  WV = `Sondaggio sugli incontri di settore del team di Steam`,
  GV = `Ciao %1$s,%2$s dove vorresti incontrarci?`,
  KV = `Di seguito sono elencati gli eventi a cui i membri del team di Steam stanno pensando di partecipare. Se anche tu stai considerando la possibilità di partecipare, o se vivi nelle vicinanze e sei disponibile per gli incontri, faccelo sapere utilizzando il modulo sottostante. Lo useremo per pianificare meglio i nostri viaggi e gli orari degli eventi. Se ti iscrivi a un evento a cui intendiamo partecipare, daremo la priorità ai partecipanti all'evento prima di inviare gli inviti a un pubblico più ampio.`,
