  EH = `Filmato di avvio`,
  DH = `Immagine di anteprima`,
  OH = `Linee guida sui video`,
  kH = `I filmati di avvio devono avere una dimensione di 1920x1200 px per la visualizzazione a schermo intero su Steam Deck. Devono essere creati tenendo in considerazione il fatto che saranno ritagliati a 1920 x 1080 px sulla maggior parte dei monitor in modalità Big Picture.`,
  AH = `Devono avere una lunghezza compresa tra 3 e 10 secondi.`,
  jH = `Possono includere il logo del tuo gioco, ma non sono consentiti altri testi o materiali di marketing.`,
  MH = `Non è permessa la trasparenza. Potresti dover disabilitare il canale alfa per l'esportazione.`,
  NH = `Il file finale deve essere in formato .webm o .mp4 e non deve essere più grande di 50 MB. Verrà compresso in un file di dimensioni ragionevoli.`,
  PH = `Linee guida sull'audio`,
  FH = `Tutti i filmati di avvio contengono sia audio che video. L'audio deve essere progettato in modo da integrarsi con l'uscita degli altoparlanti di Steam Deck e non deve essere eccessivamente alto per non disturbare l'utente all'avvio.`,
  IH = `I file audio devono essere nel formato a 16 bit con una frequenza di 48 kHz.`,
  LH = `L'output finale deve avere un volume di picco di -12 dB e un volume medio di -14 LUFS. Normalizzeremo l'audio per garantire che il volume non sia troppo alto.`,
  RH = `Evita un eccesso di frequenze medio-basse e considera l'uso di un filtro passa-alto (HPF) a partire da 40-80 Hz.`,
