  VH = `Fornisci un fermo immagine di 1920 x 1200 px tratta dal tuo filmato di avvio. Questa immagine verrà utilizzata per rappresentare il filmato di avvio nell'inventario di un utente.`,
  HH = `Sono consentiti i formati JPEG, PNG e WebP.`,
